import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

bn_tanh_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void bn_tanh_kernel(
    const float* __restrict__ in,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    const int N,
    const int C,
    const int H,
    const int W,
    const float eps
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * H * W;
    if (idx < total) {
        int w = idx % W;
        int h = (idx / W) % H;
        int c = (idx / (W * H)) % C;
        int n = idx / (W * H * C);
        int offset = ((n * C + c) * H + h) * W + w;

        float mean_c = running_mean[c];
        float var_c = running_var[c];
        float weight_c = weight[c];
        float bias_c = bias[c];
        float val = in[offset];
        val = (val - mean_c) / sqrtf(var_c + eps);
        val = weight_c * val + bias_c;
        out[offset] = tanhf(val);
    }
}

torch::Tensor bn_tanh_cuda(
    torch::Tensor x,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor weight,
    torch::Tensor bias,
    float eps
) {
    const auto N = x.size(0);
    const auto C = x.size(1);
    const auto H = x.size(2);
    const auto W = x.size(3);

    auto x_cont = x.contiguous();
    auto out = torch::empty_like(x_cont);

    const int threads = 256;
    const int total = N * C * H * W;
    const int blocks = (total + threads - 1) / threads;

    bn_tanh_kernel<<<blocks, threads>>>(
        x_cont.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, H, W,
        eps
    );
    return out;
}
"""

bn_tanh_cpp_source = r"""
torch::Tensor bn_tanh_cuda(
    torch::Tensor x,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor weight,
    torch::Tensor bias,
    float eps
);
"""

bn_tanh = load_inline(
    name="bn_tanh",
    cpp_sources=bn_tanh_cpp_source,
    cuda_sources=bn_tanh_source,
    functions=["bn_tanh_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, groups, num_groups):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, groups=groups)
        self.weight = nn.Parameter(torch.ones(out_channels))
        self.bias = nn.Parameter(torch.zeros(out_channels))
        self.running_mean = nn.Parameter(torch.zeros(out_channels), requires_grad=False)
        self.running_var = nn.Parameter(torch.ones(out_channels), requires_grad=False)
        self.eps = 1e-5
        self.max_pool = nn.MaxPool2d(kernel_size=2, stride=2)
        self.group_norm = nn.GroupNorm(num_groups=num_groups, num_channels=out_channels)

    def forward(self, x):
        x = self.conv_transpose(x)
        x = bn_tanh.bn_tanh_cuda(
            x, 
            self.running_mean, 
            self.running_var, 
            self.weight, 
            self.bias, 
            self.eps
        )
        x = self.max_pool(x)
        x = self.group_norm(x)
        return x
